    /**
     * The keys a company may use, the custom one included.
     *
     * @return list<string>
     */
    public static function claves(): array
    {
        return [...array_keys(self::REDES), self::PERSONALIZADA];
    }

    /**
     * Every listed network, as the editor offers them.
     *
     * @return list<array{clave: string, nombre: string, color: string, ejemplo: string, modo: 'relleno'|'trazo', svg: string}>
     */
    public static function catalogo(): array
    {
        return array_map(
            fn (string $clave, array $red): array => ['clave' => $clave, ...$red],
            array_keys(self::REDES),
            self::REDES,
        );
    }

    /**
     * A listed network's icon as a whole <svg>, in the color given; the
     * generic link icon for one that is not listed.
     */
    public static function svg(string $clave, string $color, string $tamano = '12px'): string
    {
        $red = self::REDES[$clave] ?? self::REDES['enlace'];
        $pintura = $red['modo'] === 'relleno'
            ? 'fill="'.e($color).'"'
            : 'fill="none" stroke="'.e($color).'" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"';

        return '<svg width="'.e($tamano).'" height="'.e($tamano).'" viewBox="0 0 24 24" '.$pintura.' xmlns="http://www.w3.org/2000/svg">'.$red['svg'].'</svg>';
    }
}
